function findMaxAverage(nums, k) {
  const reaches = (target) => {
    let prefix = 0;
    let lagging = 0;
    let minLagging = 0;
    for (let i = 0; i < k; i++) {
      prefix += nums[i] - target;
    }
    if (prefix >= 0) return true;
    for (let i = k; i < nums.length; i++) {
      prefix += nums[i] - target;
      lagging += nums[i - k] - target;
      minLagging = Math.min(minLagging, lagging);
      if (prefix - minLagging >= 0) return true;
    }
    return false;
  };

  let low = Math.min(...nums);
  let high = Math.max(...nums);
  while (high - low > 1e-7) {
    const mid = (low + high) / 2;
    if (reaches(mid)) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return low;
}

