function findMaxAverage(nums, k) {
  let best = -Infinity;
  for (let start = 0; start < nums.length; start++) {
    let sum = 0;
    for (let end = start; end < nums.length; end++) {
      sum += nums[end];
      const length = end - start + 1;
      if (length >= k && sum / length > best) best = sum / length;
    }
  }
  return best;
}

