function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  const k = rand() < 0.5 ? int(1, Math.min(n, size === 'large' ? 40 : 3)) : int(1, n);
  const span = size === 'large' || rand() < 0.2 ? 10000 : int(1, 20);
  const nums = Array.from({ length: n }, () => int(-span, span));
  return [nums, k];
}
